import{_ as a,o as i,a as r,b as t}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"附录","link":"/guide/programming_guide/appendix/show_kernel_debug_data_tool"},{"text":"FAQ","link":"/guide/programming_guide/appendix/faq/kernel_precision_issue"},{"text":"核函数（Kernel）编译时报错\\"error: out of jump/jumpc imm range\\"","link":"/guide/programming_guide/appendix/faq/kernel_compile_jump_range_error"}]},"headers":[],"relativePath":"guide/programming_guide/appendix/faq/kernel_compile_jump_range_error.md","filePath":"guide/programming_guide/appendix/faq/kernel_compile_jump_range_error.md","outlineHeaders":[{"level":2,"title":"现象描述","slug":"现象描述","link":"#现象描述"},{"level":2,"title":"问题根因","slug":"问题根因","link":"#问题根因"},{"level":2,"title":"处理步骤","slug":"处理步骤","link":"#处理步骤"}],"lastUpdated":1787050286000}'),n={name:"guide/programming_guide/appendix/faq/kernel_compile_jump_range_error.md"};function o(p,e,l,d,s,c){return i(),r("div",null,[...e[0]||(e[0]=[t(`<div><article class="markdown-body"><h1>核函数（Kernel）编译时报错“error: out of jump/jumpc imm range”<span id="ZH-CN_TOPIC_0000002033872222"></span></h1><h2 id="现象描述">现象描述<span id="section151611254194612"></span><a class="header-anchor" href="#现象描述">​</a></h2><p>使用工程化算子开发方式，基于自定义算子工程进行算子开发。编译算子时失败，报如下错误：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>[ERROR] [ascendxxxx] PowerCustom_88a695f03edfbc0af76b9eaae9e4556c error: out of jump/jumpc imm range
</code></pre></div><h2 id="问题根因">问题根因<span id="section417961104715"></span><a class="header-anchor" href="#问题根因">​</a></h2><p>该编译错误的原因是算子kernel代码过大，导致在编译时跳转指令跳转的偏移值超过了限定的大小(int16_t的数据范围)，可通过添加编译选项“-mllvm -cce-aicore-jump-expand=true”通过间接跳转的方式来避免该问题，让编译器能够正常编译。</p><h2 id="处理步骤">处理步骤<span id="section166318242419"></span><a class="header-anchor" href="#处理步骤">​</a></h2><ol><li><p>在kernel侧的CMakeLists中通过add_ops_compile_options针对报错算子添加编译选项“-mllvm -cce-aicore-jump-expand=true”，示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>add_ops_compile_options(PowerCustom OPTIONS -mllvm -cce-aicore-jump-expand=true)
</code></pre></div><p>add_ops_compile_options的具体使用方法请参考<a href="../../advanced_programming/aclnn_operator_development/compilation_and_deployment/basic_process.html#custom-compile-options">支持自定义编译选项</a>。</p></li><li><p>重新编译该算子。正常编译无报错。</p></li></ol></article></div>`,1)])])}const g=a(n,[["render",o]]);export{m as __pageData,g as default};
